    h, w = len(grid), len(grid[0])

    # Full rows and columns of the separator color partition the grid.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))
                and len({grid[r][c] for r in range(h)}) == 1]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    # The most frequent non-separator color is the background; the other
    # non-separator color is the mark being counted.
    sep = grid[sep_rows[0]][0] if sep_rows else None
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    marker = next(v for v in counts if v != background)

    out = []
    for r0, r1 in row_ranges:
        line = []
